CREATE TABLE credit_lots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),source TEXT NOT NULL,source_id TEXT,event_key TEXT NOT NULL UNIQUE,granted INTEGER NOT NULL CHECK(granted>=0),remaining INTEGER NOT NULL CHECK(remaining>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=remaining),status TEXT NOT NULL CHECK(status IN('active','archived','expired')),expires_at TEXT,archive_months INTEGER NOT NULL DEFAULT 0 CHECK(archive_months BETWEEN 0 AND 12),archive_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX credit_lots_workspace ON credit_lots(workspace_id,status,expires_at,created_at,id);
CREATE TABLE credit_lot_allocations(item_id TEXT NOT NULL,lot_id TEXT NOT NULL REFERENCES credit_lots(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),job_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN('reserved','settled','released')),refunded INTEGER NOT NULL DEFAULT 0 CHECK(refunded>=0 AND refunded<=amount),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(item_id,lot_id));
CREATE TABLE credit_lot_events(id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES credit_lots(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,amount INTEGER NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE credit_lot_operations(event_key TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,input_json TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL);
-- Previous balances have no reliable source expiry history. Preserve them explicitly as legacy, without inventing a purchase date or expiry.
INSERT INTO credit_lots(id,workspace_id,user_id,source,event_key,granted,remaining,reserved,status,created_at,updated_at)
SELECT 'legacy:'||a.workspace_id,a.workspace_id,w.created_by,'legacy','migration:legacy:'||a.workspace_id,a.balance,a.balance,a.reserved,'active',a.updated_at,a.updated_at FROM credit_accounts a JOIN workspaces w ON w.id=a.workspace_id;
INSERT INTO credit_lot_allocations(item_id,lot_id,workspace_id,job_id,user_id,amount,status,created_at,updated_at)
SELECT l.item_id,'legacy:'||l.workspace_id,l.workspace_id,l.job_id,l.user_id,l.amount,'reserved',l.created_at,l.created_at FROM credit_ledger l WHERE l.kind='reserve' AND l.amount>0 AND l.item_id IS NOT NULL AND l.job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_ledger f WHERE f.event_key='final:'||l.item_id);
-- Stop migration rather than hide any pre-existing reserved-ledger inconsistency.
CREATE TABLE credit_lot_migration_guard(valid INTEGER CHECK(valid=1));
INSERT INTO credit_lot_migration_guard SELECT CASE WHEN EXISTS(SELECT 1 FROM credit_accounts a WHERE a.reserved<>COALESCE((SELECT SUM(x.amount) FROM credit_lot_allocations x WHERE x.workspace_id=a.workspace_id AND x.status='reserved'),0)) THEN 0 ELSE 1 END;
DROP TABLE credit_lot_migration_guard;
